{

"kind": "propose",
"summary": "The api container's CPU limit is too low, causing throttling and readiness probe failures. Increasing the CPU limit to 750m should alleviate the throttling and improve performance.",
"hypotheses": [
    {
        "root_cause_class": "cpu_limit_too_low",
        "summary": "Container 'api' is consistently throttled at 0.5 CPU limit (usage 0.495), with 64% throttling ratio. Readiness probes fail due to slow response times from CPU contention.",
        "supporting": ["ev-container_cpu", "ev-target_events"],
        "contradicting": [],
        "missing": ["container_logs_tail"],
        "status": "supported"
    },
    {
        "root_cause_class": "new_version_uses_more_cpu",
        "summary": "Rollout_recent is false (revision 2 is 220h old), so recent version changes are not the cause.",
        "supporting": ["ev-rollout_history"],
        "contradicting": [],
        "missing": [],
        "status": "supported"
    }
],
"proposal": {
    "capability": "deployment.set-resources",
    "target": {"group": "apps", "kind": "Deployment", "namespace": "shop", "name": "search", "uid": "uid-deployment-search"},
    "params": {
        "containers": {
            "api": {
                "limits": {
                    "cpu": "750m"
                }
            }
        }
    },
    "expected_effect": "Raises CPU limit to 750m, reducing throttling and improving container performance to clear readiness probe timeouts.",
    "rationale": "Throttling_data_available is true, cpu_throttled_at_limit and cpu_usage_near_limit are true, and readiness probes fail. Raising the limit by 50% (to 750m) should clear the throttling without affecting memory or other containers.",
    "cited_evidence_ids": ["ev-container_cpu", "ev-target_events", "ev-rollout_history"],
    "cited_predicates": ["throttling_data_available", "cpu_throttled_at_limit", "cpu_usage_near_limit", "rollout_recent"]
}
}
